# Standalone verifier: no imports, no I/O, no filesystem, no network.
# Fail closed, exact integer arithmetic, deterministic.
# The harness evaluates VERIFY and expects the Python object True.

BOUND = 3 ** 10  # 59049

SEEDS = [[1, 2, 4], [1, 2, 3], [1, 2, 5], [1, 3, 4], [1, 4, 5]]
PERIOD = 7

def greedy(seed, bound):
    # exact canonical greedy rule: a_{n+1} = least integer > a_n
    # not of the form a_i + a_j with i, j <= n
    terms = list(seed)
    s = set()
    for i in range(len(terms)):
        for j in range(len(terms)):
            s.add(terms[i] + terms[j])
    gaps = []
    cur = terms[-1]
    while True:
        cand = cur + 1
        while cand in s:
            cand += 1
        if cand >= bound:
            break
        for x in terms:
            s.add(x + cand)
        gaps.append(cand - cur)
        terms.append(cand)
        cur = cand
    return terms, gaps

def strictly_periodic(gaps, period):
    n = len(gaps)
    if n < 3 * period:
        return False
    pat = gaps[:period]          # pattern extracted from the first period
    nwin = n // period
    for w in range(nwin):
        if gaps[w * period:(w + 1) * period] != pat:
            return False
    rem = n - nwin * period
    if rem != 0 and gaps[nwin * period:] != pat[:rem]:
        return False
    return True

def verify():
    if BOUND != 59049:
        return False
    if len(SEEDS) != 5 or PERIOD != 7:
        return False
    for seed in SEEDS:
        if len(seed) != 3:
            return False
        if not (seed[0] > 0 and seed[0] < seed[1] < seed[2]):
            return False
        terms, gaps = greedy(seed, BOUND)
        if len(terms) < 1 or terms[-1] >= BOUND:
            return False
        if gaps and not all(g in (1, 2, 3) for g in gaps):
            return False
        if not strictly_periodic(gaps, PERIOD):
            return False
    return True

VERIFY = verify()
